/* Offline ABI/equivalence adapter. No force or state transition authority. */
#include <stddef.h>
#include <string.h>
#include "engine/engine_collision_primitive.h"

typedef int (*BoxCollision)(const mjModel*, const mjData*, mjContact*, int, int, mjtNum);
typedef struct {
  mjBoxGuards guards;
  int counts[3], same_null, same_baseline;
  mjtNum contacts[3][mjMAXCONPAIR][13];
} Proof;

static int same_contact(const mjContact* a, const mjContact* b) {
  return !memcmp(&a->dist, &b->dist, sizeof(mjtNum)) &&
         !memcmp(a->pos, b->pos, 3*sizeof(mjtNum)) &&
         !memcmp(a->frame, b->frame, 9*sizeof(mjtNum));
}

MJAPI size_t a1_readout_size(void) { return sizeof(Proof); }
MJAPI int a1_readout(const mjModel* m, const mjData* d, int g1, int g2,
                    mjtNum margin, BoxCollision baseline, Proof* out) {
  if (!m || !d || !baseline || !out || g1 < 0 || g2 < 0 ||
      g1 >= m->ngeom || g2 >= m->ngeom ||
      m->geom_type[g1] != mjGEOM_BOX || m->geom_type[g2] != mjGEOM_BOX) return -1;
  mjContact observed[mjMAXCONPAIR] = {0};
  mjContact ordinary[mjMAXCONPAIR] = {0};
  mjContact original[mjMAXCONPAIR] = {0};
  memset(out, 0, sizeof(*out));
  out->counts[0] = mjc_BoxBoxGuards(m, d, observed, g1, g2, margin, &out->guards);
  out->counts[1] = mjc_BoxBox(m, d, ordinary, g1, g2, margin);
  out->counts[2] = baseline(m, d, original, g1, g2, margin);
  for (int j = 0; j < 3; j++) {
    if (out->counts[j] < 0 || out->counts[j] > mjMAXCONPAIR) return -2;
  }
  mjContact* all[3] = {observed, ordinary, original};
  for (int j = 0; j < 3; j++) {
    for (int i = 0; i < out->counts[j]; i++) {
      out->contacts[j][i][0] = all[j][i].dist;
      memcpy(out->contacts[j][i]+1, all[j][i].pos, 3*sizeof(mjtNum));
      memcpy(out->contacts[j][i]+4, all[j][i].frame, 9*sizeof(mjtNum));
    }
  }
  int n = out->counts[0];
  out->same_null = n == out->counts[1];
  out->same_baseline = n == out->counts[2];
  for (int i = 0; i < n; i++) {
    out->same_null &= i < out->counts[1] && same_contact(observed+i, ordinary+i);
    out->same_baseline &= i < out->counts[2] && same_contact(observed+i, original+i);
  }
  return 0;
}
